sp_widget.client_script:
api.controller = function($timeout) {
  var c = this;

  // These will be set once the carousel initializes
  var _goTo      = null;
  var _clearAuto = null;
  var _startAuto = null;

  // Called when user clicks Browse on a type card
  c.browseType = function(type) {
    var browseSection = document.getElementById('nx-browse');
    if (browseSection) {
      browseSection.scrollIntoView({ behavior: 'smooth' });
    }
    $timeout(function() {
      var track = document.getElementById('nxTrack');
      if (!track) return;
      var slides = track.querySelectorAll('.nx-slide');
      for (var i = 0; i < slides.length; i++) {
        var badge = slides[i].querySelector('.nx-slide-badge');
        if (badge && badge.textContent.trim() === type) {
          if (_clearAuto) _clearAuto();
          if (_goTo)      _goTo(i);
          if (_startAuto) _startAuto();
          break;
        }
      }
    }, 600);
  };

  $timeout(function() {

    var track  = document.getElementById('nxTrack');
    var dotsEl = document.getElementById('nxDots');
    var fill   = document.getElementById('nxProgressFill');

    if (!track) return;

    var slides = track.querySelectorAll('.nx-slide');
    var total  = slides.length;
    var cur    = 0;
    var delay  = 5000;
    var timer, progTimer, progStart;

    // Build dots
    for (var i = 0; i < total; i++) {
      var d = document.createElement('button');
      d.className = 'nx-dot-btn' + (i === 0 ? ' active' : '');
      d.setAttribute('data-index', i);
      dotsEl.appendChild(d);
    }

    // Dot click
    dotsEl.addEventListener('click', function(e) {
      if (e.target.classList.contains('nx-dot-btn')) {
        _clearAuto();
        _goTo(parseInt(e.target.getAttribute('data-index')));
        _startAuto();
      }
    });

    function updateDots() {
      var allDots = dotsEl.querySelectorAll('.nx-dot-btn');
      for (var i = 0; i < allDots.length; i++) {
        allDots[i].classList.toggle('active', i === cur);
      }
    }

    _goTo = function(index) {
      cur = (index + total) % total;
      track.style.transform = 'translateX(-' + (cur * 100) + '%)';
      updateDots();
      resetProgress();
    };

    function resetProgress() {
      clearInterval(progTimer);
      if (fill) {
        fill.style.transition = 'none';
        fill.style.width = '0%';
        progStart = Date.now();
        setTimeout(function() {
          progTimer = setInterval(function() {
            var pct = Math.min(((Date.now() - progStart) / delay) * 100, 100);
            fill.style.transition = 'width 0.1s linear';
            fill.style.width = pct + '%';
          }, 80);
        }, 50);
      }
    }

    _startAuto = function() {
      _clearAuto();
      resetProgress();
      timer = setInterval(function() { _goTo(cur + 1); }, delay);
    };

    _clearAuto = function() {
      clearInterval(timer);
      clearInterval(progTimer);
    };

    // Pause on hover
    var outer = document.getElementById('nxCarouselOuter');
    if (outer) {
      outer.addEventListener('mouseenter', function() { _clearAuto(); });
      outer.addEventListener('mouseleave', function() { _startAuto(); });
    }

    // Arrows
    var prevBtn = document.getElementById('nxPrev');
    var nextBtn = document.getElementById('nxNext');
    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        _clearAuto(); _goTo(cur - 1); _startAuto();
      });
    }
    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        _clearAuto(); _goTo(cur + 1); _startAuto();
      });
    }

    _startAuto();

  }, 800);
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;700;800&family=Share+Tech+Mono&family=DM+Sans:wght@300;400;500&display=swap');

.nx-page { background: #08080f; color: #f0ecff; font-family: 'DM Sans', sans-serif; }

/* NAV */
.nx-nav {
  display: flex; justify-content: space-between; align-items: center;
  padding: 0 60px; height: 68px;
  border-bottom: 1px solid rgba(184,122,255,0.12);
  background: rgba(8,8,15,0.95);
  position: sticky; top: 0; z-index: 100;
}
.nx-logo {
  font-family: 'Syne', sans-serif; font-size: 1.45rem;
  font-weight: 800; color: #f0ecff; letter-spacing: 0.04em;
}
.nx-logo span { color: #b87aff; text-shadow: 0 0 24px rgba(184,122,255,0.5); }
.nx-nav-links { display: flex; gap: 36px; }
.nx-nav-links a {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.72rem; letter-spacing: 0.18em; text-transform: uppercase;
  color: rgba(240,236,255,0.55); text-decoration: none; transition: color 0.3s;
}
.nx-nav-links a:hover { color: #b87aff; text-decoration: none; }

/* HERO */
.nx-hero { 
  padding: 80px 60px 72px; 
  position: relative; 
  background: #08080f; 
  border-bottom: 1px solid rgba(184,122,255,0.12); }
}
.nx-hero-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(184,122,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(184,122,255,0.04) 1px, transparent 1px);
  background-size: 48px 48px; pointer-events: none;
}
.nx-hero::before {
  content: ''; position: absolute;
  width: 700px; height: 500px; border-radius: 50%;
  background: radial-gradient(circle, rgba(184,122,255,0.08) 0%, transparent 65%);
  top: -160px; right: -100px; pointer-events: none;
}
.nx-hero::after {
  content: ''; position: absolute;
  width: 360px; height: 360px; border-radius: 50%;
  background: radial-gradient(circle, rgba(255,184,153,0.05) 0%, transparent 65%);
  bottom: -80px; left: 80px; pointer-events: none;
}
.nx-hero-inner { display: flex; align-items: flex-start; justify-content: space-between; gap: 40px; position: relative; z-index: 2; }
.nx-hero-content { flex: 1; max-width: 580px; }
.nx-hero-stats { flex-shrink: 0; width: 300px; display: flex; flex-direction: column; gap: 16px; position: relative; z-index: 2; }
}
.nx-stat-card {
  background: rgba(184,122,255,0.06);
  border: 1px solid rgba(184,122,255,0.18);
  border-radius: 12px; padding: 20px 24px;
  transition: border-color 0.3s;
}
.nx-stat-card:hover { border-color: rgba(184,122,255,0.35); }
.nx-stat-card-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.65rem; letter-spacing: 0.2em;
  text-transform: uppercase; color: rgba(240,236,255,0.35);
  margin-bottom: 8px; display: block;
}
.nx-stat-card-num {
  font-family: 'Syne', sans-serif; font-size: 2.4rem !important;
  font-weight: 800; color: #b87aff; line-height: 1;
  text-shadow: 0 0 20px rgba(184,122,255,0.35);
}
.nx-stat-available .nx-stat-card-num { color: #7fffb2; text-shadow: 0 0 20px rgba(127,255,178,0.4); }
.nx-stat-reservations .nx-stat-card-num { color: #ffb899; text-shadow: 0 0 20px rgba(255,184,153,0.4); }
}
.nx-stat-card-sub {
  font-size: 0.75rem; color: rgba(240,236,255,0.4);
  margin-top: 4px; display: block;
}
.nx-eyebrow {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.68rem; letter-spacing: 0.35em; color: #b87aff;
  text-transform: uppercase; margin-bottom: 22px;
  display: flex; align-items: center; gap: 12px;
}
.nx-eyebrow::before {
  content: ''; display: inline-block; width: 20px; height: 1px;
  background: #b87aff; opacity: 0.6;
}
.nx-hero h1 {
  font-family: 'Syne', sans-serif; font-size: 4.4rem;
  font-weight: 800; line-height: 1.05; color: #f0ecff; margin-bottom: 22px;
}
.nx-accent { color: #b87aff; text-shadow: 0 0 32px rgba(184,122,255,0.45); }
.nx-dot { color: #ffb899; }
.nx-sub {
  font-size: 1rem; color: rgba(240,236,255,0.55); font-weight: 300;
  max-width: 460px; line-height: 1.75; margin-bottom: 42px;
}
.nx-actions { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; }
.nx-btn-primary {
  display: inline-flex; align-items: center; gap: 10px;
  background: transparent; border: 1.5px solid #b87aff; color: #b87aff;
  font-family: 'Share Tech Mono', monospace; font-size: 0.75rem;
  letter-spacing: 0.18em; text-transform: uppercase;
  padding: 15px 32px; border-radius: 4px; text-decoration: none; transition: all 0.3s;
}
.nx-btn-primary:hover { background: rgba(184,122,255,0.14); color: #b87aff; text-decoration: none; }
.nx-btn-ghost {
  font-family: 'Share Tech Mono', monospace; font-size: 0.7rem;
  letter-spacing: 0.15em; text-transform: uppercase;
  color: rgba(240,236,255,0.28); text-decoration: none; transition: color 0.3s;
}
.nx-btn-ghost:hover { color: rgba(240,236,255,0.55); text-decoration: none; }
/* SECTION SHARED */
.nx-section { padding: 52px 60px 40px; background: #08080f; }
.nx-kb-section { padding: 32px 60px 60px; background: #08080f; }
.nx-section-header {
  display: flex; align-items: center; gap: 14px; margin-bottom: 28px;
}
.nx-tag {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.65rem; letter-spacing: 0.25em; text-transform: uppercase;
  color: #b87aff; background: rgba(184,122,255,0.14);
  border: 1px solid rgba(184,122,255,0.24); padding: 5px 14px; border-radius: 3px;
}
.nx-section-line { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(184,122,255,0.12), transparent); }
.nx-section-count {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.62rem; color: rgba(240,236,255,0.28); letter-spacing: 0.1em;
}

/* TYPE CARDS — Section 1 */
.nx-type-cards {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
}
.nx-type-card {
  background: #0e0c1a; border: 1px solid rgba(184,122,255,0.12);
  border-radius: 12px; overflow: hidden;
  transition: border-color 0.3s, transform 0.3s;
}
.nx-type-card:hover { border-color: rgba(184,122,255,0.3); transform: translateY(-4px); }
.nx-type-img-wrap { position: relative; height: 160px; overflow: hidden; }
.nx-type-img-wrap img {
  width: 100%; height: 100%; object-fit: cover;
  filter: saturate(0.7) brightness(0.8); transition: filter 0.4s;
}
.nx-type-card:hover .nx-type-img-wrap img { filter: saturate(0.9) brightness(0.9); }
.nx-type-img-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, #0e0c1a 100%);
}
.nx-type-body { padding: 16px 18px 20px; }
.nx-type-name {
  font-family: 'Syne', sans-serif; font-size: 1rem;
  font-weight: 700; color: #f0ecff; margin-bottom: 8px;
}
.nx-type-desc {
  font-size: 0.78rem; color: rgba(240,236,255,0.45);
  line-height: 1.6; font-weight: 300; margin-bottom: 16px;
}
.nx-type-footer {
  display: flex; justify-content: space-between; align-items: center;
}
.nx-type-avail {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.65rem; color: #7fffb2;
  display: flex; align-items: center; gap: 6px;
}
.nx-type-cta {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.62rem; letter-spacing: 0.15em; text-transform: uppercase;
  color: #b87aff; text-decoration: none; transition: opacity 0.2s;
}
.nx-type-cta:hover { opacity: 0.7; text-decoration: none; }
/* PROGRESS BAR */
.nx-progress-wrap {
  height: 2px; background: rgba(184,122,255,0.1);
  overflow: hidden; margin-bottom: 0;
}
.nx-progress-fill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, #b87aff, #ffb899);
  transition: width 0.1s linear;
}

/* CAROUSEL */
.nx-carousel-outer {
  overflow: hidden; border-radius: 16px;
  border: 1px solid rgba(184,122,255,0.12);
  box-shadow: 0 24px 80px rgba(0,0,0,0.5);
}
.nx-carousel-track {
  display: flex;
  transition: transform 0.75s cubic-bezier(0.77,0,0.18,1);
}
.nx-slide {
  min-width: 100%; display: flex; height: 500px; background: #0e0c1a;
}
.nx-slide-img { flex: 0 0 56%; position: relative; overflow: hidden; }
.nx-slide-img img {
  width: 100%; height: 100%; object-fit: cover;
  filter: saturate(0.75) brightness(0.85);
  transition: transform 1.2s ease;
}
.nx-slide:hover .nx-slide-img img { transform: scale(1.04); }
.nx-slide-img::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to right, rgba(26,13,48,0.25) 0%, transparent 60%);
}
.nx-slide-badge {
  position: absolute; top: 24px; left: 24px; z-index: 2;
  background: #b87aff; color: #fff;
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.6rem; letter-spacing: 0.2em; text-transform: uppercase;
  padding: 5px 14px; border-radius: 40px;
}
.nx-slide-details {
  flex: 1; display: flex; flex-direction: column;
  justify-content: center; padding: 48px 44px;
  background: linear-gradient(150deg, #1a0d30 0%, #0f0820 100%);
  position: relative; overflow: hidden;
}
.nx-slide-details-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(184,122,255,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(184,122,255,0.04) 1px, transparent 1px);
  background-size: 32px 32px;
}
.nx-slide-num {
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.62rem; letter-spacing: 0.25em;
  color: #b87aff; opacity: 0.7; margin-bottom: 10px;
  position: relative; z-index: 1; text-transform: uppercase;
}
.nx-slide-title {
  font-family: 'Syne', sans-serif; font-size: 2rem;
  font-weight: 800; color: #fff; line-height: 1.15;
  margin-bottom: 14px; position: relative; z-index: 1;
}
.nx-slide-desc {
  font-size: 0.85rem; color: rgba(255,255,255,0.6);
  line-height: 1.75; font-weight: 300; margin-bottom: 28px;
  max-width: 300px; position: relative; z-index: 1;
}
.nx-slide-meta {
  display: flex; flex-direction: column; gap: 10px;
  margin-bottom: 32px; position: relative; z-index: 1;
}
.nx-meta-row { display: flex; align-items: center; gap: 10px; }
.nx-meta-icon {
  width: 30px; height: 30px; border-radius: 7px;
  background: rgba(184,122,255,0.12);
  border: 1px solid rgba(184,122,255,0.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 0.9rem; flex-shrink: 0;
}
.nx-meta-label {
  font-family: 'Share Tech Mono', monospace; font-size: 0.58rem;
  letter-spacing: 0.15em; text-transform: uppercase;
  color: #b87aff; opacity: 0.6; display: block; margin-bottom: 2px;
}
.nx-meta-value { font-size: 0.85rem; color: rgba(255,255,255,0.85); display: block; }
.nx-status-av { color: #7fffb2 !important; }
.nx-slide-cta {
  display: inline-flex; align-items: center; gap: 10px;
  background: transparent; border: 1.5px solid #b87aff; color: #b87aff;
  font-family: 'Share Tech Mono', monospace; font-size: 0.7rem;
  letter-spacing: 0.18em; text-transform: uppercase;
  padding: 13px 26px; border-radius: 4px; text-decoration: none;
  transition: all 0.3s; align-self: flex-start; position: relative; z-index: 1;
}
.nx-slide-cta:hover { background: rgba(184,122,255,0.14); color: #b87aff; text-decoration: none; }

/* CAROUSEL CONTROLS */
.nx-carousel-controls {
  display: flex; align-items: center;
  justify-content: center; gap: 20px; margin-top: 28px;
}
.nx-ctrl-btn {
  width: 46px; height: 46px; border-radius: 50%;
  border: 1.5px solid rgba(184,122,255,0.24);
  background: transparent; color: rgba(240,236,255,0.55);
  font-size: 1.1rem; cursor: pointer;
  display: flex; align-items: center; justify-content: center; transition: all 0.3s;
}
.nx-ctrl-btn:hover { background: rgba(184,122,255,0.14); border-color: #b87aff; color: #b87aff; }
.nx-dots { display: flex; gap: 8px; align-items: center; }
.nx-dot-btn {
  width: 7px; height: 7px; border-radius: 50%;
  background: rgba(184,122,255,0.25); border: none;
  cursor: pointer; transition: all 0.3s; padding: 0;
}
.nx-dot-btn.active { background: #b87aff; width: 22px; border-radius: 4px; }
/* STATUS DOTS */
.nx-dot-g { width: 7px; height: 7px; border-radius: 50%; background: #7fffb2; box-shadow: 0 0 6px #7fffb2; display: inline-block; flex-shrink: 0; }
.nx-dot-r { width: 7px; height: 7px; border-radius: 50%; background: #ff6b6b; box-shadow: 0 0 6px #ff6b6b; display: inline-block; flex-shrink: 0; }
.nx-dot-o { width: 7px; height: 7px; border-radius: 50%; background: #ffaa44; box-shadow: 0 0 6px #ffaa44; display: inline-block; flex-shrink: 0; }

/* KB STRIP */
.nx-kb-cards { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
.nx-kb-card {
  background: #0e0c1a; border: 1px solid rgba(184,122,255,0.12);
  border-radius: 10px; padding: 24px 24px 20px;
  transition: border-color 0.3s, transform 0.3s;
  text-decoration: none; display: block;
}
.nx-kb-card:hover { border-color: rgba(184,122,255,0.24); transform: translateY(-3px); text-decoration: none; }
.nx-kb-icon { font-size: 1.4rem; margin-bottom: 14px; display: block; }
.nx-kb-title {
  font-family: 'Syne', sans-serif; font-size: 0.92rem;
  font-weight: 700; color: #f0ecff; margin-bottom: 8px;
}
.nx-kb-link {
  font-family: 'Share Tech Mono', monospace; font-size: 0.62rem;
  letter-spacing: 0.15em; text-transform: uppercase;
  color: #b87aff; margin-top: 16px; display: inline-block;
}

/* FOOTER */
.nx-footer {
  border-top: 1px solid rgba(184,122,255,0.12);
  padding: 24px 60px; display: flex;
  justify-content: space-between; align-items: center;
  background: #08080f;
}
.nx-footer-logo {
  font-family: 'Syne', sans-serif; font-size: 0.9rem;
  font-weight: 700; color: rgba(240,236,255,0.28);
}
.nx-footer-logo span { color: #b87aff; }
.nx-footer-copy {
  font-family: 'Share Tech Mono', monospace; font-size: 0.6rem;
  color: rgba(240,236,255,0.28); letter-spacing: 0.15em;
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .nx-type-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 900px) {
  .nx-nav { padding: 0 20px; }
  .nx-hero { padding: 48px 24px; }
  .nx-hero h1 { font-size: 2.6rem; }
  .nx-section, .nx-kb-section { padding-left: 20px; padding-right: 20px; }
  .nx-type-cards { grid-template-columns: repeat(2, 1fr); }
  .nx-slide { flex-direction: column; height: auto; }
  .nx-slide-img { flex: 0 0 220px; }
  .nx-kb-cards { grid-template-columns: 1fr; }
  .nx-nav-links { gap: 16px; }
}
@media (max-width: 600px) {
  .nx-type-cards { grid-template-columns: 1fr; }
  .nx-nav-links a { font-size: 0.6rem; letter-spacing: 0.1em; }
}

/* GREETING CARD */
.nx-stat-greeting { min-height: 110px; justify-content: center; display: flex; flex-direction: column; }
.nx-stat-card-greeting {
  font-family: 'Syne', sans-serif; font-size: 1.1rem;
  font-weight: 700; color: #f0ecff; line-height: 1.2;
  display: block; margin-bottom: 2px;
}
.nx-stat-card-name {
  font-family: 'Syne', sans-serif; font-size: 1.6rem;
  font-weight: 800; color: #ffb899; line-height: 1;
  text-shadow: 0 0 20px rgba(255,184,153,0.4);
  display: block;
}
.nx-stat-link {
  color: #b87aff !important; text-decoration: none;
  font-family: 'Share Tech Mono', monospace;
  font-size: 0.72rem !important; letter-spacing: 0.1em;
  transition: opacity 0.2s; display: block; margin-top: 6px;
}
.nx-stat-link:hover { opacity: 0.7; text-decoration: none; }

/* FONT SIZE BUMPS */
.nx-nav-links a { font-size: 0.82rem !important; }
.nx-eyebrow { font-size: 0.82rem !important; }
.nx-sub { font-size: 1.1rem !important; }
.nx-tag { font-size: 0.75rem !important; }
.nx-section-count { font-size: 0.75rem !important; }
.nx-type-name { font-size: 1.1rem !important; }
.nx-type-desc { font-size: 0.88rem !important; }
.nx-type-avail { font-size: 0.78rem !important; }
.nx-type-cta { font-size: 0.75rem !important; }
.nx-slide-num { font-size: 0.78rem !important; }
.nx-slide-title { font-size: 2.2rem !important; }
.nx-slide-desc { font-size: 0.95rem !important; }
.nx-meta-label { font-size: 0.72rem !important; }
.nx-meta-value { font-size: 0.95rem !important; }
.nx-slide-cta { font-size: 0.82rem !important; }
.nx-avail-eyebrow { font-size: 0.75rem !important; }
.nx-avail-room-name { font-size: 0.88rem !important; }
.nx-badge { font-size: 0.72rem !important; }
.nx-kb-title { font-size: 1.05rem !important; }
.nx-kb-link { font-size: 0.75rem !important; }
.nx-stat-card-label { font-size: 0.75rem !important; }
.nx-stat-card-num { font-size: 2.4rem !important; }
.nx-stat-card-sub { font-size: 0.85rem !important; }
.nx-footer-copy { font-size: 0.72rem !important; }
.nx-btn-primary { font-size: 0.85rem !important; }
.nx-btn-ghost { font-size: 0.82rem !important; }

/* FONT SIZE TWEAKS */
.nx-nav-links a { font-size: 0.9rem !important; letter-spacing: 0.14em !important; }
.nx-eyebrow { font-size: 0.85rem !important; letter-spacing: 0.28em !important; }
.nx-tag { font-size: 0.8rem !important; letter-spacing: 0.2em !important; }
.nx-section-count { font-size: 0.82rem !important; }
.nx-stat-card-label { font-size: 0.8rem !important; letter-spacing: 0.18em !important; }
.nx-stat-card-greeting { font-size: 1.2rem !important; }
.nx-stat-card-sub { font-size: 0.88rem !important; }
.nx-stat-link { font-size: 0.78rem !important; }

sp_widget.script:
(function() {

    data.catalogItemId = '2ab07725c3eb32109f0231cc050131f6';

    // ── GREETING ─────────────────────────────────
    data.greeting = 'Hello';
    data.userName = gs.getUser().getFirstName() || gs.getUserDisplayName();

    // ── MY ACTIVE RESERVATIONS COUNT ─────────────
    var myRes = new GlideRecord('x_746154_workspa_0_reservation_tracker');
    myRes.addQuery('reserved_for', gs.getUserID());
    myRes.addQuery('reservation_status', 'IN', 'pending_check_in,checked_in');
    myRes.query();
    data.myReservationCount = myRes.getRowCount();

    // ── WORKSPACE TYPE CARDS ──────────────────────
    var typeImages = {
        'Collaboration Space': 'https://i.postimg.cc/Bb1G0z1v/collaboration-space.jpg',
        'Focus Room':          'https://i.postimg.cc/4yhTg0hn/focus-room.jpg',
        'Hot Desk':            'https://i.postimg.cc/T1WX6sWK/hot-desk.jpg',
        'Meeting Room':        'https://i.postimg.cc/3W5QJZg7/meeting-room.jpg'
    };
    var typeDescriptions = {
        'Collaboration Space': 'Open areas designed for team brainstorming, workshops, and creative sessions. Equipped with whiteboards and modular furniture.',
        'Focus Room':          'Private soundproof rooms for deep work, confidential calls, and distraction-free productivity.',
        'Hot Desk':            'Flexible open desks available on demand. Perfect for individuals needing a quick, functional workspace.',
        'Meeting Room':        'Professional conference rooms with video conferencing, presentation screens, and seating for teams.'
    };
    var typeCounts = {};
    var typeTotal  = {};
    var ws = new GlideRecord('x_746154_workspa_0_workspace_options');
    ws.addQuery('status', '!=', 'decommissioned');
    ws.query();
    while (ws.next()) {
        var t = ws.getDisplayValue('workspace_type');
        if (!typeTotal[t])  typeTotal[t]  = 0;
        if (!typeCounts[t]) typeCounts[t] = 0;
        typeTotal[t]++;
        if (ws.getDisplayValue('status').toLowerCase() === 'available') {
            typeCounts[t]++;
        }
    }
    var typeCards = [];
    var typeOrder = ['Hot Desk', 'Focus Room', 'Collaboration Space', 'Meeting Room'];
    for (var i = 0; i < typeOrder.length; i++) {
        var type = typeOrder[i];
        typeCards.push({
            type:        type,
            image:       typeImages[type],
            description: typeDescriptions[type],
            available:   typeCounts[type] || 0,
            total:       typeTotal[type]  || 0
        });
    }
    data.typeCards = typeCards;

    // ── BROWSE SPACES ─────────────────────────────
    var rooms = [];
    var gr = new GlideRecord('x_746154_workspa_0_workspace_options');
    gr.addQuery('status', 'available');
    gr.orderBy('workspace_type');
    gr.orderBy('workspace_name');
    gr.query();
    while (gr.next()) {
        rooms.push({
            name:         gr.getDisplayValue('workspace_name'),
            type:         gr.getDisplayValue('workspace_type'),
            location:     gr.getDisplayValue('location'),
            maxOccupancy: gr.getDisplayValue('max_occupancy'),
            status:       gr.getDisplayValue('status'),
            description:  gr.getDisplayValue('workspace_description'),
            sysId:        gr.getUniqueValue()
        });
    }
    data.rooms = rooms;
    data.totalAvailable = rooms.length;

    // ── KB ARTICLES ───────────────────────────────
    var articles = [];
    var kb = new GlideRecord('kb_knowledge');
    kb.addActiveQuery();
    kb.addQuery('short_description', 'CONTAINS', 'workspace');
    kb.setLimit(3);
    kb.query();
    while (kb.next()) {
        articles.push({
            title: kb.getDisplayValue('short_description'),
            sysId: kb.getUniqueValue()
        });
    }
    if (articles.length === 0) {
    articles = [
        { title: 'Cancellation Policy',       sysId: 'f7f24ae3c3d043109f0231cc05013158' },
        { title: 'Reservation Confirmations', sysId: '7a0586a7c3d043109f0231cc0501318a' },
        { title: 'Maintenance Issues',         sysId: 'bf9b02efc3d043109f0231cc0501319a' }
    ];
}
    data.articles = articles;

})();
